<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { RouterLink, useRoute } from 'vue-router';
import { useI18n } from 'vue-i18n';
import { downloadFile, get, post, del } from '../api/client';
import { session } from '../api/session';
import { Button, Card, Field, Input, Select, EmptyState } from '../components/ui';
interface Statement { id: number; reference: string; title: string; partnerName: string; direction: string; currency: string; fromDay: string; toDay: string; dueDay: string | null; lines: { label: string; amount: string }[]; total: string; publicNote: string; status: string; version: number; issuedAt: string | null; cancelReason: string | null; createdAt: string }
interface Evidence { scope: { fromDay: string; toDay: string }; supplierCostUsd?: string | null; costRecords?: number; records: number; days: { day: string; scanStatus: string }[] }
interface Internal { siteId: number; partnerId: number; internalNote: string; sourceReviewId: number | null; sourceEvidence: Evidence | null }
interface Share { id: number; status: string; note: string; version: number; revokedAt: string | null; email?: string; accessId?: number }
interface Receipt { id: number; amount: string; reference: string; method: string; receivedDay: string; note: string; voidedAt: string | null; voidReason: string | null }
interface Event { id: number; action: string; note: string; createdAt: string }
interface Grant { id: number; email: string; role: string; partnerId: number | null; acceptedAt: string | null; revokedAt: string | null; expiresAt: string }
interface Totals { recorded: string; remaining: string; status: string; overdue: boolean }
const route=useRoute(), { locale }=useI18n(), l=(zh:string,en:string)=>locale.value.startsWith('zh')?zh:en;
const canManage=computed(()=>session.state.user?.role!=='viewer'&&session.state.workspaceRole==='owner');
const manage=ref(canManage.value&&(route.query.mode==='manage'||session.state.user?.role==='root')),busy=ref(false),error=ref(''),notice=ref('');
const base=computed(()=>manage.value?'/api/services/settlements':'/api/collaboration/settlements');
const sites=ref<{id:number;label:string}[]>([]),siteId=ref<string|number|null>(null),partners=ref<{id:number;name:string;status:string}[]>([]),grants=ref<Grant[]>([]);
const items=ref<{item:Statement;share?:Share}[]>([]),more=ref(false),selected=ref<number|null>(null),item=ref<Statement|null>(null),internal=ref<Internal|null>(null),share=ref<Share|null>(null),totals=ref<Totals|null>(null);
const receipts=ref<Receipt[]>([]),events=ref<Event[]>([]),shares=ref<Share[]>([]),moreReceipts=ref(false),moreEvents=ref(false),moreShares=ref(false);
const today=()=>new Date(Date.now()+8*3600000).toISOString().slice(0,10);
const editing=ref(false),draft=ref(blank()),sourceEvidence=ref<Evidence|null>(null),sourceReviewId=ref<number|null>(null),issuedAck=ref(false),cancelReason=ref('');
const receipt=ref(blankReceipt()),receiptAck=ref(false),voidReasons=ref<Record<number,string>>({}),responseNote=ref(''),responseStatus=ref<string|number>('acknowledged');
const recipient=ref<string|number|null>(null),preview=ref<{document:Statement;recipient:{email:string;role:string};balance:Totals;receipts:Receipt[];hasOlderReceipts:boolean;confirmation:string}|null>(null),shareAck=ref(false);
function blank(){return{reference:'',title:'',partnerId:null as string|number|null,direction:'payable',currency:'USD',fromDay:today(),toDay:today(),dueDay:'',lines:[{label:'',amount:''}],publicNote:'',internalNote:''};}
function blankReceipt(){return{amount:'',reference:'',method:'',receivedDay:today(),note:''};}
const labels:Record<string,[string,string]>={draft:['草稿','Draft'],issued:['已出单','Issued'],cancelled:['已取消','Cancelled'],payable:['应付给伙伴','Payable to partner'],receivable:['应收自伙伴','Receivable from partner'],unrecorded:['未登记回执','No receipts recorded'],partially_recorded:['已登记部分回执','Partial receipts recorded'],recorded_in_full:['已登记足额回执','Full receipts recorded'],pending:['待对方回复','Awaiting response'],acknowledged:['对方已确认','Acknowledged'],disputed:['对方有异议','Disputed']};
const label=(s:string)=>labels[s]?l(...labels[s]):s;
const amount=(v:string|null|undefined)=>v==null?'—':v.replace(/(\.\d*?[1-9])0+$|\.0+$/,'$1');
const options=(keys:string[])=>keys.map(value=>({value,label:label(value)}));
const eligible=computed(()=>grants.value.filter(g=>g.acceptedAt&&!g.revokedAt&&Date.parse(g.expiresAt+'Z')>Date.now()&&['supplier','reseller','finance'].includes(g.role)&&(g.partnerId===null?g.role==='finance':g.partnerId===internal.value?.partnerId)));
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=String(e);}finally{busy.value=false;}}
function reset(){selected.value=null;item.value=null;internal.value=null;share.value=null;editing.value=false;preview.value=null;sourceEvidence.value=null;sourceReviewId.value=null;receipts.value=[];events.value=[];shares.value=[];issuedAck.value=false;receipt.value=blankReceipt();receiptAck.value=false;voidReasons.value={};cancelReason.value='';responseNote.value='';responseStatus.value='acknowledged';recipient.value=null;shareAck.value=false;}
function discard(){return !editing.value||window.confirm(l('放弃尚未保存的草稿修改？','Discard unsaved draft changes?'));}
async function list(append=false){
 const before=append?items.value.at(-1):undefined;
 if(manage.value){if(!siteId.value){items.value=[];return;}const r=await get<{items:Statement[];hasMore:boolean}>(`${base.value}?siteId=${siteId.value}${before?`&beforeId=${before.item.id}`:''}`);items.value=append?[...items.value,...r.items.map(item=>({item}))]:r.items.map(item=>({item}));more.value=r.hasMore;}
 else{const r=await get<{items:typeof items.value;hasMore:boolean}>(`${base.value}${before?.share?`?beforeId=${before.share.id}`:''}`);items.value=append?[...items.value,...r.items]:r.items;more.value=r.hasMore;}
}
async function siteResources(){if(!siteId.value)return;const [p,g]=await Promise.all([get<{items:typeof partners.value}>(`/api/services/partners?siteId=${siteId.value}`),get<{items:Grant[];limited:boolean}>(`/api/services/collaboration/access?siteId=${siteId.value}`)]);partners.value=p.items;grants.value=g.items;}
async function init(){reset();if(manage.value){const r=await get<{sites:typeof sites.value}>('/api/services/catalog');sites.value=r.sites;siteId.value=r.sites.find(s=>String(s.id)===route.query.site)?.id??r.sites[0]?.id??null;await siteResources();}await list();}
async function switchMode(value:boolean){if(!discard())return;manage.value=value;await action(init);}
async function chooseSite(value:string|number|null){if(!discard())return;siteId.value=value;reset();await action(async()=>{await siteResources();await list();});}
async function pageRows(kind:'receipts'|'events'|'shares',append=false){
 if(!selected.value)return;
 async function load<T extends {id:number}>(rows:{value:T[]},hasMore:{value:boolean}){
  const before=append?rows.value.at(-1)?.id:undefined;
  const r=await get<{items:T[];hasMore:boolean}>(`${base.value}/${selected.value}/${kind}${before?`?beforeId=${before}`:''}`);
  rows.value=append?[...rows.value,...r.items]:r.items;hasMore.value=r.hasMore;
 }
 if(kind==='receipts')await load(receipts,moreReceipts);
 else if(kind==='events')await load(events,moreEvents);
 else await load(shares,moreShares);
}
async function detail(){if(!selected.value)return;const r=await get<{item:Statement;balance:Totals;internal?:Internal;share?:Share}>(`${base.value}/${selected.value}`);item.value=r.item;totals.value=r.balance;internal.value=r.internal??null;share.value=r.share??null;preview.value=null;shareAck.value=false;issuedAck.value=false;await Promise.all([pageRows('receipts'),pageRows('events'),...(manage.value?[pageRows('shares')]:[])]);}
async function open(row:typeof items.value[number]){if(!discard())return;reset();selected.value=manage.value?row.item.id:row.share!.id;await action(detail);}
function create(){if(!discard())return;reset();draft.value=blank();draft.value.partnerId=partners.value.find(p=>p.status==='active')?.id??null;editing.value=true;}
function edit(){const s=item.value,i=internal.value;if(!s||!i)return;draft.value={reference:s.reference,title:s.title,partnerId:i.partnerId,direction:s.direction,currency:s.currency,fromDay:s.fromDay,toDay:s.toDay,dueDay:s.dueDay??'',lines:s.lines.map(r=>({...r})),publicNote:s.publicNote,internalNote:i.internalNote};sourceReviewId.value=i.sourceReviewId;sourceEvidence.value=i.sourceEvidence;editing.value=true;}
async function save(){await action(async()=>{const b={...draft.value,siteId:Number(siteId.value),partnerId:Number(draft.value.partnerId),dueDay:draft.value.dueDay||null,sourceReviewId:sourceReviewId.value,version:item.value?.version??0};const r=await post<{item:Statement}>(`${base.value}${item.value?`/${item.value.id}`:''}`,b);selected.value=r.item.id;editing.value=false;await list();await detail();});}
async function command(path:string,b:object){if(!selected.value)return;await post(`${base.value}/${selected.value}/${path}`,b);await list();await detail();}
async function recordReceipt(){await action(async()=>{await command('receipts',{...receipt.value,version:item.value!.version,acknowledge:receiptAck.value});receipt.value=blankReceipt();receiptAck.value=false;});}
async function sharePreview(){await action(async()=>{preview.value=await post(`/api/services/settlements/${selected.value}/share-preview`,{accessId:Number(recipient.value)});shareAck.value=false;});}
async function shareDocument(){if(!preview.value)return;await action(async()=>{await post(`/api/services/settlements/${selected.value}/shares`,{accessId:Number(recipient.value),confirmation:preview.value!.confirmation,acknowledge:shareAck.value});await detail();});}
async function revoke(s:Share){await action(async()=>{await del(`/api/services/settlements/${selected.value}/shares/${s.id}`);await pageRows('shares');});}
async function respond(){await action(async()=>{await post(`${base.value}/${selected.value}/respond`,{version:share.value!.version,status:responseStatus.value,note:responseNote.value});responseNote.value='';await detail();await list();});}
async function exportCsv() { await action(() => downloadFile(`${base.value}/${selected.value}/export.csv`, 'settlement.csv')); }
watch(recipient,()=>{preview.value=null;shareAck.value=false;});
onMounted(()=>void action(async()=>{await init();if(manage.value&&typeof route.query.source==='string'){const r=await get<{siteId:number;reviewId:number;evidence:Evidence;amount:string}>(`/api/services/settlements/sources/${encodeURIComponent(route.query.source)}`);siteId.value=r.siteId;await siteResources();await list();create();sourceEvidence.value=r.evidence;sourceReviewId.value=r.reviewId;draft.value.fromDay=r.evidence.scope.fromDay;draft.value.toDay=r.evidence.scope.toDay;draft.value.lines=[{label:l('已观测上游成本（待核对）','Observed supplier cost (requires verification)'),amount:r.amount}];}}));
</script>

<template>
 <div class="rp-page space-y-5">
  <div><h1 class="text-xl font-semibold">{{ l('合作结算单','Partner statements') }}</h1><p class="mt-2 max-w-3xl text-sm leading-6 text-muted">{{ l('核对合作金额、共享结算单并登记分次收付款回执。金额与回执由操作员确认；面板不执行转账，不把登记记录当作银行或支付平台的验证结果。','Review agreed amounts, share statements and record partial receipts. Operators confirm the amounts and references. The panel makes no transfers and does not verify provider settlement.') }}</p></div>
  <div class="flex flex-wrap gap-2"><Button v-if="canManage" :variant="manage?'primary':'outline'" :disabled="busy" @click="switchMode(true)">{{ l('我管理的结算单','Managed statements') }}</Button><Button :variant="!manage?'primary':'outline'" :disabled="busy" @click="switchMode(false)">{{ l('共享给我的结算单','Shared with me') }}</Button><RouterLink to="/collaboration" class="self-center text-sm text-accent">{{ l('管理协作身份','Manage collaboration access') }}</RouterLink></div>
  <p v-if="error" role="alert" class="rounded border border-red/30 bg-red/10 p-3 text-sm text-red">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
  <div v-if="manage" class="flex flex-wrap items-end gap-3"><Field :label="l('当前站点','Site')"><Select :model-value="siteId" :options="sites.map(s=>({value:s.id,label:s.label}))" :disabled="busy" @update:model-value="chooseSite" /></Field><Button :disabled="busy||!siteId" @click="create">{{ l('新建结算单','New statement') }}</Button></div>
  <div class="grid items-start gap-5 xl:grid-cols-[minmax(250px,1fr)_minmax(0,2fr)]">
   <Card class="min-w-0 [&>div]:space-y-3"><Button size="sm" variant="ghost" :disabled="busy" @click="action(()=>list())">{{ l('刷新列表','Refresh list') }}</Button><p v-if="!items.length" class="text-sm text-muted">{{ l('暂无结算单。协作邀请不会自动共享任何账单。','No statements. A collaboration invitation does not automatically share any statement.') }}</p><button v-for="r in items" :key="r.share?.id??r.item.id" class="block w-full rounded-lg border border-border p-3 text-left hover:border-accent disabled:opacity-50" :disabled="busy" @click="open(r)"><span class="block break-words text-sm font-medium">{{ r.item.title }}</span><span class="mt-1 block break-words text-xs text-muted">{{ r.item.reference }} · {{ label(r.item.status) }}<br />{{ r.item.partnerName }} · {{ amount(r.item.total) }} {{ r.item.currency }}</span></button><Button v-if="more" variant="ghost" size="sm" :disabled="busy" @click="action(()=>list(true))">{{ l('更早结算单','Older statements') }}</Button></Card>
   <div class="min-w-0 space-y-4">
    <Card v-if="editing" class="[&>div]:space-y-4"><h2 class="font-semibold">{{ item?l('修改草稿','Edit draft'):l('创建草稿','Create draft') }}</h2>
     <p v-if="sourceEvidence" class="text-xs leading-6 text-amber">{{ l('已引用账目复核快照。已知成本记录','Imported finance review snapshot. Priced cost records') }} {{ sourceEvidence.costRecords??0 }}/{{ sourceEvidence.records }} · {{ l('读取完成天数','Completed scan days') }} {{ sourceEvidence.days.filter(d=>d.scanStatus==='complete').length }}/{{ sourceEvidence.days.length }}。{{ l('观测金额不是供应商确认金额，请核对后再出单。原始快照保持内部可见。','Observed costs are not supplier-confirmed amounts. Verify before issuing. The source snapshot remains private.') }}</p>
     <form class="space-y-4" @submit.prevent="save"><fieldset :disabled="busy" class="min-w-0 space-y-4">
      <div class="grid gap-3 sm:grid-cols-2"><Field :label="l('合作伙伴','Partner')"><Select v-model="draft.partnerId" :options="partners.filter(p=>p.status==='active'||p.id===internal?.partnerId).map(p=>({value:p.id,label:p.name}))" :disabled="!!item" /></Field><Field :label="l('结算单号','Statement reference')"><Input v-model="draft.reference" maxlength="100" required :disabled="!!item" /></Field></div>
      <p v-if="!partners.length" class="text-xs text-muted">{{ l('请先在站点服务中心建立合作伙伴档案。','Create a partner in the site service center first.') }} <RouterLink :to="{path:'/services',query:{site:String(siteId)}}" class="text-accent">{{ l('前往服务中心','Open service center') }}</RouterLink></p>
      <Field :label="l('标题','Title')"><Input v-model="draft.title" minlength="3" maxlength="160" required /></Field>
      <div class="grid gap-3 sm:grid-cols-2"><Field :label="l('方向（站点方视角）','Direction (site perspective)')"><Select v-model="draft.direction" :options="options(['payable','receivable'])" :disabled="!!sourceReviewId" /></Field><Field :label="l('币种','Currency')"><Select v-model="draft.currency" :options="[{value:'USD',label:'USD'},{value:'CNY',label:'CNY'}]" :disabled="!!sourceReviewId" /></Field><Field :label="l('账期开始','Period start')"><Input v-model="draft.fromDay" type="date" required :disabled="!!sourceReviewId" /></Field><Field :label="l('账期结束','Period end')"><Input v-model="draft.toDay" type="date" required :disabled="!!sourceReviewId" /></Field><Field :label="l('约定到期日（可选，北京时间）','Due date (optional, Asia/Shanghai)')"><Input v-model="draft.dueDay" type="date" /></Field></div>
      <div class="space-y-3"><p class="text-sm">{{ l('金额明细：折让可填负数，净额须为正数；不换汇。','Line amounts: credits may be negative; the net total must be positive. No currency conversion.') }}</p><div v-for="(line,index) in draft.lines" :key="index" class="grid gap-2 rounded border border-border p-3 sm:grid-cols-[1fr_160px_auto]"><Field :label="l('明细说明','Description')"><Input v-model="line.label" maxlength="200" required /></Field><Field :label="l('金额（最多六位小数）','Amount (up to six decimals)')"><Input v-model="line.amount" inputmode="decimal" pattern="-?(0|[1-9][0-9]{0,9})(\.[0-9]{1,6})?" required /></Field><Button size="sm" variant="ghost" class="self-end" :disabled="draft.lines.length===1" @click="draft.lines.splice(index,1)">{{ l('移除','Remove') }}</Button></div><Button variant="outline" size="sm" :disabled="draft.lines.length>=50" @click="draft.lines.push({label:'',amount:''})">{{ l('添加明细','Add line') }}</Button></div>
      <Field :label="l('对外说明（共享后对方可见）','Public note (visible when shared)')"><textarea v-model="draft.publicNote" maxlength="2000" class="min-h-20 w-full rounded border border-border bg-bg/60 p-3 text-sm" /></Field><Field :label="l('内部备注（仅管理方可见）','Internal note (management only)')"><textarea v-model="draft.internalNote" maxlength="4000" class="min-h-20 w-full rounded border border-border bg-bg/60 p-3 text-sm" /></Field>
      <Button type="submit" :disabled="!draft.partnerId">{{ l('保存草稿','Save draft') }}</Button><Button variant="ghost" @click="editing=false">{{ l('收起编辑','Close editor') }}</Button>
     </fieldset></form>
    </Card>
    <template v-if="item&&!editing">
     <Card class="[&>div]:space-y-4"><div class="flex flex-wrap justify-between gap-3"><div><h2 class="break-words font-semibold">{{ item.title }}</h2><p class="mt-1 break-words text-xs text-muted">{{ item.reference }} · {{ item.partnerName }} · {{ label(item.status) }} · v{{ item.version }}</p></div><div class="flex flex-wrap gap-2"><Button size="sm" variant="outline" :disabled="busy" @click="action(detail)">{{ l('刷新详情','Refresh details') }}</Button><Button size="sm" variant="outline" :disabled="busy" @click="exportCsv">{{ l('导出结算单','Export statement') }}</Button><Button v-if="manage&&item.status==='draft'" size="sm" :disabled="busy" @click="edit">{{ l('修改草稿','Edit draft') }}</Button></div></div>
      <p class="text-xs text-muted">{{ label(item.direction) }} · {{ item.fromDay }} — {{ item.toDay }}<span v-if="item.dueDay"> · {{ l('到期','Due') }} {{ item.dueDay }}</span></p>
      <div class="overflow-x-auto"><table class="w-full text-sm"><tbody><tr v-for="(line,index) in item.lines" :key="index" class="border-b border-border"><td class="break-words p-2">{{ line.label }}</td><td class="whitespace-nowrap p-2 text-right">{{ amount(line.amount) }} {{ item.currency }}</td></tr></tbody></table></div>
      <p class="text-lg font-semibold">{{ l('合计','Total') }} {{ amount(item.total) }} {{ item.currency }}</p><p v-if="item.publicNote" class="whitespace-pre-wrap break-words text-sm">{{ item.publicNote }}</p><p v-if="item.cancelReason" class="whitespace-pre-wrap break-words text-sm text-red">{{ l('取消原因','Cancellation reason') }}: {{ item.cancelReason }}</p>
      <div v-if="totals" class="rounded border border-border p-3 text-sm leading-7"><p>{{ label(totals.status) }} · {{ amount(totals.recorded) }} {{ item.currency }}</p><p>{{ l('尚未登记','Unrecorded amount') }} {{ amount(totals.remaining) }} {{ item.currency }}<span v-if="totals.overdue" class="ml-2 text-amber">{{ l('已过约定到期日','Past due date') }}</span></p><p class="text-xs text-muted">{{ l('仅根据有效回执记录计算，不代表已核验真实到账。','Calculated from active receipt records, not verified provider settlement.') }}</p></div>
      <details v-if="internal" class="text-xs"><summary class="cursor-pointer">{{ l('内部备注与来源（不共享）','Internal notes and source (not shared)') }}</summary><p class="mt-2 whitespace-pre-wrap break-words">{{ internal.internalNote||'—' }}</p><p v-if="internal.sourceEvidence" class="mt-2 leading-6">{{ l('引用账目复核','Finance review') }} #{{ internal.sourceReviewId }} · {{ l('观测成本','Observed cost') }} {{ amount(internal.sourceEvidence.supplierCostUsd) }} USD · {{ internal.sourceEvidence.costRecords??0 }}/{{ internal.sourceEvidence.records }} {{ l('条成本记录','priced cost records') }}</p></details>
      <form v-if="manage&&item.status==='draft'" class="space-y-3 border-t border-border pt-3" @submit.prevent="action(()=>command('issue',{version:item!.version,acknowledge:issuedAck}))"><label class="flex items-start gap-2 text-xs leading-6"><input v-model="issuedAck" type="checkbox" required class="mt-1.5" /><span>{{ l('已核对金额、币种、账期和依据。出单后冻结这些内容，修改须取消并重建。','I verified amounts, currency, period and evidence. Issuing freezes these fields; corrections require cancellation and a new statement.') }}</span></label><Button type="submit" :disabled="busy||!issuedAck">{{ l('确认出单','Issue statement') }}</Button></form>
      <details v-if="manage&&item.status!=='cancelled'"><summary class="cursor-pointer text-xs text-muted">{{ l('取消结算单','Cancel statement') }}</summary><form class="mt-3 space-y-3" @submit.prevent="action(()=>command('cancel',{version:item!.version,reason:cancelReason}))"><Field :label="l('取消原因（对方可见）','Cancellation reason (shared)')"><textarea v-model="cancelReason" minlength="5" maxlength="2000" required class="min-h-20 w-full rounded border border-border bg-bg/60 p-3 text-sm" /></Field><Button type="submit" variant="outline" :disabled="busy||!!totals&&totals.recorded!=='0.000000'">{{ l('记录取消','Record cancellation') }}</Button></form></details>
     </Card>
     <Card class="[&>div]:space-y-4"><h2 class="font-semibold">{{ l('收付款回执记录','Receipt records') }}</h2><p v-if="!receipts.length" class="text-sm text-muted">{{ l('尚未登记回执。','No receipts recorded.') }}</p><article v-for="r in receipts" :key="r.id" class="space-y-2 rounded border border-border p-3 text-sm"><p class="break-words">{{ r.reference }} · {{ amount(r.amount) }} {{ item.currency }} <span v-if="r.voidedAt" class="text-red">{{ l('已作废','Voided') }}</span></p><p class="text-xs text-muted">{{ r.receivedDay }} · {{ r.method }}</p><p v-if="r.note" class="whitespace-pre-wrap break-words text-xs">{{ r.note }}</p><p v-if="r.voidReason" class="whitespace-pre-wrap break-words text-xs">{{ r.voidReason }}</p><details v-if="manage&&!r.voidedAt"><summary class="cursor-pointer text-xs">{{ l('更正：作废此记录','Correction: void this record') }}</summary><form class="mt-2 space-y-2" @submit.prevent="action(()=>command(`receipts/${r.id}/void`,{version:item!.version,reason:voidReasons[r.id]}))"><Field :label="l('作废原因（对方可见）','Void reason (shared)')"><textarea v-model="voidReasons[r.id]" required minlength="5" maxlength="2000" class="min-h-20 w-full rounded border border-border bg-bg/60 p-3 text-sm" /></Field><p class="text-xs text-muted">{{ l('仅更正登记记录，不执行退款。有效余额将重新计算。','Corrects the record only, without a refund. Recorded totals will be recalculated.') }}</p><Button type="submit" size="sm" variant="outline" :disabled="busy">{{ l('作废记录','Void record') }}</Button></form></details></article><Button v-if="moreReceipts" variant="ghost" size="sm" :disabled="busy" @click="action(()=>pageRows('receipts',true))">{{ l('更早回执','Older receipts') }}</Button>
      <details v-if="manage&&item.status==='issued'"><summary class="cursor-pointer text-sm font-medium">{{ l('登记一笔回执','Record a receipt') }}</summary><form class="mt-3 space-y-3" @submit.prevent="recordReceipt"><fieldset :disabled="busy" class="space-y-3"><div class="grid gap-3 sm:grid-cols-2"><Field :label="l('本次金额','Receipt amount')"><Input v-model="receipt.amount" inputmode="decimal" pattern="(0|[1-9][0-9]{0,9})(\.[0-9]{1,6})?" required /></Field><Field :label="l('真实回执编号','Receipt reference')"><Input v-model="receipt.reference" required minlength="3" maxlength="160" /></Field><Field :label="l('收付款方式','Payment method')"><Input v-model="receipt.method" required minlength="2" maxlength="80" /></Field><Field :label="l('实际发生日期（北京时间）','Receipt date (Asia/Shanghai)')"><Input v-model="receipt.receivedDay" type="date" :max="today()" required /></Field></div><Field :label="l('回执说明（共享后对方可见）','Receipt note (visible when shared)')"><textarea v-model="receipt.note" maxlength="2000" class="min-h-20 w-full rounded border border-border bg-bg/60 p-3 text-sm" /></Field><label class="flex items-start gap-2 text-xs leading-6"><input v-model="receiptAck" type="checkbox" required class="mt-1.5" /><span>{{ l('已在收付款渠道核对这笔真实回执，登记不会发起付款或退款。','I checked this real receipt in the payment channel. Recording it does not initiate a payment or refund.') }}</span></label><Button type="submit" :disabled="!receiptAck">{{ l('保存回执记录','Save receipt record') }}</Button></fieldset></form></details>
     </Card>
     <Card v-if="manage" class="[&>div]:space-y-4"><h2 class="font-semibold">{{ l('共享与对方回复','Sharing and responses') }}</h2><div v-if="item.status==='issued'" class="space-y-3"><Field :label="l('选择已接受邀请的协作者','Choose an accepted collaborator')"><Select v-model="recipient" :options="eligible.map(g=>({value:g.id,label:`${g.email} · ${g.role}`}))" :disabled="busy" /></Field><p class="text-xs leading-6 text-muted">{{ l('只共享本单公开内容及当前、后续回执记录。内部备注和原始账目快照不共享；同一伙伴的供应商/代理身份或财务身份可接收。邀请不会自动发送。','Shares this statement and its current and future receipt records. Internal notes and source evidence remain private. Eligible recipients are this partner’s supplier/reseller identity or finance collaborators. No email is sent.') }}</p><Button variant="outline" size="sm" :disabled="busy||!recipient" @click="sharePreview">{{ l('预览共享内容','Preview sharing') }}</Button>
       <div v-if="preview" class="space-y-3 rounded border border-accent/40 p-3"><p class="break-words text-sm">{{ l('收件身份','Recipient') }}: {{ preview.recipient.email }} · {{ preview.recipient.role }}</p><p class="text-sm">{{ preview.document.title }} · {{ preview.document.reference }} · {{ amount(preview.document.total) }} {{ preview.document.currency }}</p><p class="break-words text-xs">{{ preview.document.partnerName }} · {{ label(preview.document.direction) }} · {{ preview.document.fromDay }} — {{ preview.document.toDay }}<span v-if="preview.document.dueDay"> · {{ l('到期','Due') }} {{ preview.document.dueDay }}</span></p><p v-for="(line,index) in preview.document.lines" :key="index" class="break-words text-xs">{{ line.label }} · {{ amount(line.amount) }} {{ preview.document.currency }}</p><p class="whitespace-pre-wrap break-words text-xs">{{ preview.document.publicNote||'—' }}</p><p class="text-xs">{{ l('当前已登记回执','Currently recorded') }} {{ amount(preview.balance.recorded) }} {{ preview.document.currency }}</p><p v-for="r in preview.receipts" :key="r.id" class="break-words text-xs">{{ r.reference }} · {{ r.method }} · {{ amount(r.amount) }} · {{ r.note }} · {{ r.voidReason }}</p><p v-if="preview.hasOlderReceipts" class="text-xs text-muted">{{ l('还有更早回执；共享后对方可分页查看完整记录。','Older receipts also exist; the recipient can page through the full history.') }}</p><label class="flex items-start gap-2 text-xs leading-6"><input v-model="shareAck" type="checkbox" class="mt-1.5" /><span>{{ l('确认向上述身份共享本单公开内容和全部回执记录。','Share this statement’s public contents and all receipt records with the identity above.') }}</span></label><Button size="sm" :disabled="busy||!shareAck" @click="shareDocument">{{ l('确认共享','Confirm sharing') }}</Button></div>
      </div><article v-for="s in shares" :key="s.id" class="space-y-2 rounded border border-border p-3 text-xs"><p class="break-words">{{ s.email }} · {{ label(s.status) }} · {{ s.revokedAt?l('已撤销','Revoked'):l('已共享','Shared') }}</p><p class="whitespace-pre-wrap break-words">{{ s.note||'—' }}</p><Button v-if="!s.revokedAt" size="sm" variant="ghost" :disabled="busy" @click="revoke(s)">{{ l('撤销此共享','Revoke sharing') }}</Button></article><Button v-if="moreShares" variant="ghost" size="sm" :disabled="busy" @click="action(()=>pageRows('shares',true))">{{ l('更早共享记录','Older shares') }}</Button></Card>
     <Card v-else-if="share&&item.status==='issued'" class="[&>div]:space-y-3"><h2 class="font-semibold">{{ l('向站点方回复','Respond to the site owner') }}</h2><p class="text-xs text-muted">{{ l('回复仅对管理方和你可见；确认账单不等于确认到账。','Your response is visible to management and you. Acknowledging a statement does not confirm payment.') }}</p><form class="space-y-3" @submit.prevent="respond"><Field :label="l('回复状态','Response')"><Select v-model="responseStatus" :options="options(['acknowledged','disputed'])" :disabled="busy" /></Field><Field :label="l('回复说明','Response note')"><textarea v-model="responseNote" required minlength="5" maxlength="2000" class="min-h-20 w-full rounded border border-border bg-bg/60 p-3 text-sm" /></Field><Button type="submit" :disabled="busy">{{ l('提交回复','Send response') }}</Button></form></Card>
     <Card class="[&>div]:space-y-3"><h2 class="font-semibold">{{ l('处理历史','Activity history') }}</h2><article v-for="e in events" :key="e.id" class="border-b border-border pb-3 text-xs"><p class="text-muted">{{ e.createdAt }} UTC</p><p class="mt-1 whitespace-pre-wrap break-words">{{ e.note }}</p></article><Button v-if="moreEvents" size="sm" variant="ghost" :disabled="busy" @click="action(()=>pageRows('events',true))">{{ l('更早历史','Older activity') }}</Button></Card>
    </template>
    <EmptyState v-else-if="!editing" :title="l('选择或创建一张结算单','Select or create a statement')" :description="l('草稿、对外确认与回执分别留痕；共享可以随时撤销。','Drafts, responses and receipt records have separate history. Sharing can be revoked.')" />
   </div>
  </div>
 </div>
</template>
